action.command:
node -e "
const fs = require('fs');
const path = require('path');
const localesDir = path.join(process.cwd(), 'src', 'packs', 'language', 'locales');
if (!fs.existsSync(localesDir)) process.exit(0);
const enPath = path.join(localesDir, 'en.json');
if (!fs.existsSync(enPath)) process.exit(0);
const en = JSON.parse(fs.readFileSync(enPath, 'utf8'));
const enKeys = Object.keys(en);
const coreLocales = ['ms', 'zh-Hans', 'zh-Hant', 'ta', 'es'];
let missing = [];
for (const locale of coreLocales) {
  const lPath = path.join(localesDir, locale + '.json');
  if (!fs.existsSync(lPath)) { missing.push(locale + ': FILE MISSING'); continue; }
  const lData = JSON.parse(fs.readFileSync(lPath, 'utf8'));
  const lKeys = Object.keys(lData);
  const missingKeys = enKeys.filter(k => !lKeys.includes(k));
  if (missingKeys.length) {
    missing.push(locale + ': missing keys: ' + missingKeys.join(', '));
    // Auto-add [MT] placeholders
    for (const k of missingKeys) {
      lData[k] = '[MT] ' + en[k];
    }
    fs.writeFileSync(lPath, JSON.stringify(lData, null, 2) + '\n');
  }
}
if (missing.length) { console.log('Locale sync:\n' + missing.join('\n')); }
else { console.log('All core locales in sync.'); }
"
